// Format the §13.4 daily report
const rows = $input.all().map(i => i.json);
const total = rows.reduce((a, r) => a + Number(r.count), 0);
const bySrc = {};
for (const r of rows) {
  if (!bySrc[r.source]) bySrc[r.source] = { total: 0, paths: {} };
  bySrc[r.source].total += Number(r.count);
  bySrc[r.source].paths[r.path || 'unknown'] = Number(r.count);
}
const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
let text = `:bar_chart: *R360 Inbound — ${yesterday}*\nTotal: *${total}* leads\n\n`;
for (const [src, data] of Object.entries(bySrc)) {
  text += `• \`${src}\`: ${data.total}`;
  const pathSummary = Object.entries(data.paths).map(([p, c]) => `${p}=${c}`).join(', ');
  text += `  _(${pathSummary})_\n`;
}
return [{ json: { reportText: text, total, byForm: bySrc } }];
